class Solution {
public:
    vector<int> closestDivisors(int num) {
        vector<int> best;
        int diff = INT_MAX;
        for (int x : {num + 1, num + 2}) {
            for (int d = (int)sqrt(x); d >= 1; --d) {
                if (x % d == 0) {
                    if (x / d - d < diff) {
                        diff = x / d - d;
                        best = {d, x / d};
                    }
                    break;
                }
            }
        }
        return best;
    }
};
